static int CalculateMaxDifferenceSum(List<Integer> sequence) {
    int total_sum = 0;
    int n = sequence.size();
    for (int i = 0; i < n - 1; i++) {
        for (int j = i + 1; j < n; j++) {
            int difference = sequence.get(j) - sequence.get(i);
            if (difference > 0) {
                total_sum += difference;
            }
        }
    }
    return total_sum;
}
